(window.__qhadithX=window.__qhadithX||{})[59]={"5":[{"c":"Sahih Bukhari","r":"Hadith 4031","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4031","x":"Narrated Ibn `Umar:\n\nAllah's Messenger (ﷺ) had the date-palm trees of Bani Al-Nadir burnt and cut down at a place called Al- Buwaira. Allah then revealed: \"What you cut down of the date-palm trees (of the enemy) Or you left them standing on their stems. It was by Allah's Permission.\" (59.5)","ar":"حَدَّثَنَا آدَمُ، حَدَّثَنَا اللَّيْثُ، عَنْ نَافِعٍ، عَنِ ابْنِ عُمَرَ ـ رضى الله عنهما ـ قَالَ حَرَّقَ رَسُولُ اللَّهِ صلى الله عليه وسلم نَخْلَ بَنِي النَّضِيرِ وَقَطَعَ وَهْىَ الْبُوَيْرَةُ فَنَزَلَتْ ‏{‏مَا قَطَعْتُمْ مِنْ لِينَةٍ أَوْ تَرَكْتُمُوهَا قَائِمَةً عَلَى أُصُولِهَا فَبِإِذْنِ اللَّهِ‏}‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4884","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4884","x":"Narrated Ibn `Umar:\n\n'Allah's Messenger (ﷺ) burnt and cut down the palm trees of Bani An-Nadir which were at Al-Buwair (a place near Medina). There upon Allah revealed: 'What you (O Muslims) cut down of the palm trees (of the enemy) or you left them standing on their stems, it was by the leave of Allah, so that He might cover with shame the rebellious.' (59.5)","ar":"حَدَّثَنَا قُتَيْبَةُ، حَدَّثَنَا لَيْثٌ، عَنْ نَافِعٍ، عَنِ ابْنِ عُمَرَ ـ رضى الله عنهما ـ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم حَرَّقَ نَخْلَ بَنِي النَّضِيرِ وَقَطَعَ، وَهْىَ الْبُوَيْرَةُ، فَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏مَا قَطَعْتُمْ مِنْ لِينَةٍ أَوْ تَرَكْتُمُوهَا قَائِمَةً عَلَى أُصُولِهَا فَبِإِذْنِ اللَّهِ وَلِيُخْزِيَ الْفَاسِقِينَ‏}‏","v":[]},{"c":"Sunan Ibn Majah","r":"Volume 4, Book 24, Hadith 2844","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-4/Book-24/Hadith-2844","x":"It was narrated from Ibn ‘Umar that the Messenger of Allah (ﷺ) burned the palm trees of Banu Nadir, and cut down Buwairah (the name of their garden). Then Allah revealed the words:\n\n\"What you (O Muslims) cut down of the palm trees (of the enemy), or you left them standing...\" [59:5]","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ رُمْحٍ، أَنْبَأَنَا اللَّيْثُ بْنُ سَعْدٍ، عَنْ نَافِعٍ، عَنِ ابْنِ عُمَرَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم حَرَّقَ نَخْلَ بَنِي النَّضِيرِ وَقَطَعَ ‏.‏ وَهِيَ الْبُوَيْرَةُ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏{مَا قَطَعْتُمْ مِنْ لِينَةٍ أَوْ تَرَكْتُمُوهَا قَائِمَةً }‏ الآيَةَ ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 1746a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-1746a","x":"It is narrated on the authority of 'Abdullah that the Messenger of Allah (ﷺ) ordered the date-palms of Banu Nadir to be burnt and cut. These palms were at Buwaira. Qutaibah and Ibn Rumh in their versions of the tradition have added:\n\nSo Allah, the Glorious and Exalted, revealed the verse:\" Whatever trees you have cut down or left standing on their trunks, it was with the permission of Allah so that He may disgrace the evil-doers\" (lix. 5).","ar":"حَدَّثَنَا يَحْيَى بْنُ يَحْيَى، وَمُحَمَّدُ بْنُ رُمْحٍ، قَالاَ أَخْبَرَنَا اللَّيْثُ، ح وَحَدَّثَنَا قُتَيْبَةُ بْنُ، سَعِيدٍ حَدَّثَنَا لَيْثٌ، عَنْ نَافِعٍ، عَنْ عَبْدِ اللَّهِ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم حَرَّقَ نَخْلَ بَنِي النَّضِيرِ وَقَطَعَ وَهِيَ الْبُوَيْرَةُ ‏.‏ زَادَ قُتَيْبَةُ وَابْنُ رُمْحٍ فِي حَدِيثِهِمَا فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏{‏ مَا قَطَعْتُمْ مِنْ لِينَةٍ أَوْ تَرَكْتُمُوهَا قَائِمَةً عَلَى أُصُولِهَا فَبِإِذْنِ اللَّهِ وَلِيُخْزِيَ الْفَاسِقِينَ‏}‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 3, Book 19, Hadith 1552","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-3/Book-19/Hadith-1552","x":"Narrated Ibn 'Umar:\n\n\"The Messenger of Allah (ﷺ) burnt the palm trees of Bani Nadir and cut them down at Al-Buwairah. So Allah revealed: Whatever you cut down of their palm trees, or you left them standing on their trunks, then it was by the permission of Allah, and in the order to disgrace the rebellious.(59:5)\"","ar":"حَدَّثَنَا قُتَيْبَةُ، حَدَّثَنَا اللَّيْثُ، عَنْ نَافِعٍ، عَنِ ابْنِ عُمَرَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم حَرَّقَ نَخْلَ بَنِي النَّضِيرِ وَقَطَعَ وَهِيَ الْبُوَيْرَةُ فَأَنْزَلَ اللَّهُ ‏:‏ ‏(‏ مَا قَطَعْتُمْ مِنْ لِينَةٍ أَوْ تَرَكْتُمُوهَا قَائِمَةً عَلَى أُصُولِهَا فَبِإِذْنِ اللَّهِ وَلِيُخْزِيَ الْفَاسِقِينَ ‏)‏ ‏.‏ قَالَ وَفِي الْبَابِ عَنِ ابْنِ عَبَّاسٍ ‏.‏ وَهَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏ وَقَدْ ذَهَبَ قَوْمٌ مِنْ أَهْلِ الْعِلْمِ إِلَى هَذَا وَلَمْ يَرَوْا بَأْسًا بِقَطْعِ الأَشْجَارِ وَتَخْرِيبِ الْحُصُونِ ‏.‏ وَكَرِهَ بَعْضُهُمْ ذَلِكَ وَهُوَ قَوْلُ الأَوْزَاعِيِّ ‏.‏ قَالَ الأَوْزَاعِيُّ وَنَهَى أَبُو بَكْرٍ الصِّدِّيقُ يَزِيدَ أَنْ يَقْطَعَ شَجَرًا مُثْمِرًا أَوْ يُخَرِّبَ عَامِرًا وَعَمِلَ بِذَلِكَ الْمُسْلِمُونَ بَعْدَهُ ‏.‏ وَقَالَ الشَّافِعِيُّ لاَ بَأْسَ بِالتَّحْرِيقِ فِي أَرْضِ الْعَدُوِّ وَقَطْعِ الأَشْجَارِ وَالثِّمَارِ ‏.‏ وَقَالَ أَحْمَدُ وَقَدْ تَكُونُ فِي مَوَاضِعَ لاَ يَجِدُونَ مِنْهُ بُدًّا فَأَمَّا بِالْعَبَثِ فَلاَ تُحَرَّقُ ‏.‏ وَقَالَ إِسْحَاقُ التَّحْرِيقُ سُنَّةٌ إِذَا كَانَ أَنْكَى فِيهِمْ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 6, Book 44, Hadith 3302","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-6/Book-44/Hadith-3302","x":"Ibn Umar [may Allah be pleased with him] said:\n\n\"The Messenger of Allah ordered burning and cutting down the date palms of Banu An-Nadir, and that (place was called Al-Buwairah. So Allah revealed: What you cut down of the Linah, or you left of them standing on their trunks, it was by the leave of Allah, and in order that He might disgrace the rebellious.\"","ar":"حَدَّثَنَا قُتَيْبَةُ، حَدَّثَنَا اللَّيْثُ، عَنْ نَافِعٍ، عَنِ ابْنِ عُمَرَ، رضى الله عنهما قَالَ حَرَّقَ رَسُولُ اللَّهِ صلى الله عليه وسلم نَخْلَ بَنِي النَّضِيرِ وَقَطَّعَ وَهِيَ الْبُوَيْرَةُ فَأَنْزَلَ اللَّهُ ‏:‏ ‏(‏ما قَطَعْتُمْ مِنْ لِينَةٍ أَوْ تَرَكْتُمُوهَا قَائِمَةً عَلَى أُصُولِهَا فَبِإِذْنِ اللَّهِ وَلِيُخْزِيَ الْفَاسِقِينَ ‏)‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 6, Book 44, Hadith 3303","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-6/Book-44/Hadith-3303","x":"Hafs bin Ghiyath narrated:\n\n\"Habib bin Abi Amrah narrated to us, from Sa’eed bin Jubair, from Ibn Abbas, regarding the saying of Allah, the Mighty and Sublime: What you cut down of the Linah, or you left of them standing on their trunks – he said: ‘The Linah is the date-palms.’ That He might disgrace the rebellious. He said: ‘They were forced from their forts.’ And they were ordered to cut down the date-pals, that caused some hesitation in their chests, so the Muslims said: \"We cut some of them, and we left some of them, so let us ask the Messenger of Allah is we are to be rewarded for those that we cut down, and if we will be burdened for what we left?\" So Allah [Most High] revealed the Ayah: What you cut down of the Linah, or you left of them standing on their trunks.\"","ar":"حَدَّثَنَا الْحَسَنُ بْنُ مُحَمَّدٍ الزَّعْفَرَانِيُّ، حَدَّثَنَا عَفَّانُ بْنُ مُسْلِمٍ، حَدَّثَنَا حَفْصُ بْنُ غِيَاثٍ، حَدَّثَنَا حَبِيبُ بْنُ أَبِي عَمْرَةَ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، عَنِ ابْنِ عَبَّاسٍ، فِي قَوْلِ اللَّهِ عَزَّ وَجَلَّ ‏:‏ ‏(‏ما قَطَعْتُمْ مِنْ لِينَةٍ أَوْ تَرَكْتُمُوهَا قَائِمَةً عَلَى أُصُولِهَا ‏)‏ ‏.‏ قَالَ اللِّينَةُ النَّخْلَةُِيُخْزِيَ الْفَاسِقِينَ ‏)‏ قَالَ اسْتَنْزَلُوهُمْ مِنْ حُصُونِهِمْ قَالَ وَأَمَرُوا بِقَطْعِ النَّخْلِ فَحَكَّ فِي صُدُورِهِمْ ‏.‏ فَقَالَ الْمُسْلِمُونَ قَدْ قَطَعْنَا بَعْضًا وَتَرَكْنَا بَعْضًا فَلَنَسْأَلَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم هَلْ لَنَا فِيمَا قَطَعْنَا مِنْ أَجْرٍ وَهَلْ عَلَيْنَا فِيمَا تَرَكْنَا مِنْ وِزْرٍ فَأَنْزَلَ اللَّهُ تَعَالَى ‏:‏ ‏(‏ما قَطَعْتُمْ مِنْ لِينَةٍ أَوْ تَرَكْتُمُوهَا قَائِمَةً عَلَى أُصُولِهَا ‏)‏ ‏.‏ الآيَةَ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ غَرِيبٌ ‏.‏ وَرَوَى بَعْضُهُمْ، هَذَا الْحَدِيثَ عَنْ حَفْصِ بْنِ غِيَاثٍ، عَنْ حَبِيبِ بْنِ أَبِي عَمْرَةَ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، مُرْسَلاً وَلَمْ يَذْكُرْ فِيهِ عَنِ ابْنِ عَبَّاسٍ، ‏.‏ حَدَّثَنِي بِذَلِكَ عَبْدُ اللَّهِ بْنُ عَبْدِ الرَّحْمَنِ، حَدَّثَنَا هَارُونُ بْنُ مُعَاوِيَةَ، عَنْ حَفْصِ بْنِ غِيَاثٍ، عَنْ حَبِيبِ بْنِ أَبِي عَمْرَةَ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم مُرْسَلاً ‏.‏ قَالَ أَبُو عِيسَى سَمِعَ مِنِّي مُحَمَّدُ بْنُ إِسْمَاعِيلَ هَذَا الْحَدِيثَ ‏.‏","v":[]}],"6":[{"c":"Sunan Abu Dawud","r":"Hadith 2972","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2972","x":"Narrated Umar ibn AbdulAziz:\n\nAl-Mughirah (ibn Shu'bah) said: Umar ibn AbdulAziz gathered the family of Marwan when he was made caliph, and he said: Fadak belonged to the Messenger of Allah (ﷺ), and he made contributions from it, showing repeated kindness to the poor of the Banu Hashim from it, and supplying from it the cost of marriage for those who were unmarried. Fatimah asked him to give it to her, but he refused. That is how matters stood during the lifetime of the Messenger of Allah (ﷺ) till he passed on (i.e. died). When AbuBakr was made ruler he administered it as the Prophet (ﷺ) had done in his lifetime till he passed on. Then when Umar ibn al-Khattab was made ruler he administered it as they had done till he passed on. Then it was given to Marwan as a fief, and it afterwards came to Umar ibn AbdulAziz. Umar ibn AbdulAziz said: I consider I have no right to something which the Messenger of Allah (ﷺ) refused to Fatimah, and I call you to witness that I have restored it to its former condition; meaning in the time of the Messenger of Allah (ﷺ). Abu Dawud said: When 'Umar b. 'Abd al-'Aziz was made caliph its revenue was forty thousand dinars, and when he died its revenue was four hundred dinars. Had he remained alive, it would have been less than it.","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ الْجَرَّاحِ، حَدَّثَنَا جَرِيرٌ، عَنِ الْمُغِيرَةِ، قَالَ جَمَعَ عُمَرُ بْنُ عَبْدِ الْعَزِيزِ بَنِي مَرْوَانَ حِينَ اسْتُخْلِفَ فَقَالَ إِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم كَانَتْ لَهُ فَدَكُ فَكَانَ يُنْفِقُ مِنْهَا وَيَعُودُ مِنْهَا عَلَى صَغِيرِ بَنِي هَاشِمٍ وَيُزَوِّجُ مِنْهَا أَيِّمَهُمْ وَإِنَّ فَاطِمَةَ سَأَلَتْهُ أَنْ يَجْعَلَهَا لَهَا فَأَبَى فَكَانَتْ كَذَلِكَ فِي حَيَاةِ رَسُولِ اللَّهِ صلى الله عليه وسلم حَتَّى مَضَى لِسَبِيلِهِ فَلَمَّا أَنْ وَلِيَ أَبُو بَكْرٍ رضى الله عنه عَمِلَ فِيهَا بِمَا عَمِلَ النَّبِيُّ صلى الله عليه وسلم فِي حَيَاتِهِ حَتَّى مَضَى لِسَبِيلِهِ فَلَمَّا أَنْ وَلِيَ عُمَرُ عَمِلَ فِيهَا بِمِثْلِ مَا عَمِلاَ حَتَّى مَضَى لِسَبِيلِهِ ثُمَّ أَقْطَعَهَا مَرْوَانُ ثُمَّ صَارَتْ لِعُمَرَ بْنِ عَبْدِ الْعَزِيزِ قَالَ - يَعْنِي عُمَرَ بْنَ عَبْدِ الْعَزِيزِ - فَرَأَيْتُ أَمْرًا مَنَعَهُ رَسُولُ اللَّهِ صلى الله عليه وسلم فَاطِمَةَ عَلَيْهَا السَّلاَمُ لَيْسَ لِي بِحَقٍّ وَأَنَا أُشْهِدُكُمْ أَنِّي قَدْ رَدَدْتُهَا عَلَى مَا كَانَتْ يَعْنِي عَلَى عَهْدِ رَسُولِ اللَّهِ صلى الله عليه وسلم ‏.‏ قَالَ أَبُو دَاوُدَ وَلِيَ عُمَرُ بْنُ عَبْدِ الْعَزِيزِ الْخِلاَفَةَ وَغَلَّتُهُ أَرْبَعُونَ أَلْفَ دِينَارٍ وَتُوُفِّيَ وَغَلَّتُهُ أَرْبَعُمِائَةِ دِينَارٍ وَلَوْ بَقِيَ لَكَانَ أَقَلَّ ‏.‏","v":[]},{"c":"Sunan Abu Dawud","r":"Hadith 2977","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2977","x":"A similar tradition has been narrated by Ibn Shihab through a different chain of narrators. This version says:\n\nI said: Do you not fear Allah ? Did you not hear the Messenger of Allah (ﷺ) say: We are not inherited. Whatever we leave is sadaqah (alms). This property belongs to the family of Muhammad for their emergent needs and their guest. When I die, it will go to him who becomes ruler after me.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ يَحْيَى بْنِ فَارِسٍ، حَدَّثَنَا إِبْرَاهِيمُ بْنُ حَمْزَةَ، حَدَّثَنَا حَاتِمُ بْنُ إِسْمَاعِيلَ، عَنْ أُسَامَةَ بْنِ زَيْدٍ، عَنِ ابْنِ شِهَابٍ، بِإِسْنَادِهِ نَحْوَهُ قُلْتُ أَلاَ تَتَّقِينَ اللَّهَ أَلَمْ تَسْمَعْنَ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ ‏\n\n\"‏ لاَ نُورَثُ مَا تَرَكْنَا فَهُوَ صَدَقَةٌ وَإِنَّمَا هَذَا الْمَالُ لآلِ مُحَمَّدٍ لِنَائِبَتِهِمْ وَلِضَيْفِهِمْ فَإِذَا مِتُّ فَهُوَ إِلَى مَنْ وَلِيَ الأَمْرَ مِنْ بَعْدِي ‏\"\n\n‏ ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4033","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4033","x":"Narrated Malik bin Aus Al-Hadathan An-Nasri:\n\nThat once `Umar bin Al-Khattab called him and while he was sitting with him, his gatekeeper, Yarfa came and said, \"Will you admit `Uthman, `Abdur-Rahman bin `Auf, AzZubair and Sa`d (bin Abi Waqqas) who are waiting for your permission?\" `Umar said, \"Yes, let them come in.\" After a while, Yarfa- came again and said, \"Will you admit `Ali and `Abbas who are asking your permission?\" `Umar said, \"Yes.\" So, when the two entered, `Abbas said, \"O chief of the believers! Judge between me and this (i.e. `Ali). \"Both of them had a dispute regarding the property of Bani An-Nadir which Allah had given to His Apostle as Fai (i.e. booty gained without fighting), `Ali and `Abbas started reproaching each other. The (present) people (i.e. `Uthman and his companions) said, \"O chief of the believers! Give your verdict in their case and relieve each from) the other.\" `Umar said, \"Wait I beseech you, by Allah, by Whose Permission both the heaven and the earth stand fast! Do you know that Allah's Messenger (ﷺ) said, 'We (Prophets) our properties are not to be inherited, and whatever we leave, is to be spent in charity,' and he said it about himself?\" They (i.e. `Uthman and his company) said, \"He did say it. \"`Umar then turned towards `Ali and `Abbas and said, \"I beseech you both, by Allah! Do you know that Allah's Messenger (ﷺ) said this?\" They replied in the affirmative. He said, \"Now I am talking to you about this matter. Allah the Glorified favored His Apostle with something of this Fai (i.e. booty won without fighting) which He did not give to anybody else. Allah said:-- \"And what Allah gave to His Apostle (\"Fai\"\" Booty) from them--For which you made no expedition With either Calvary or camelry. But Allah gives power to His Apostles Over whomsoever He will And Allah is able to do all things.\" (59.6) So this property was especially granted to Allah's Messenger (ﷺ). But by Allah, the Prophet (ﷺ) neither took it all for himself only, nor deprived you of it, but he gave it to all of you and distributed it amongst you till only this remained out of it. And from this Allah's Messenger (ﷺ) used to spend the yearly maintenance for his family, and whatever used to remain, he used to spend it where Allah's Property is spent (i.e. in charity), Allah's Messenger (ﷺ) kept on acting like that during all his life, Then he died, and Abu Bakr said, 'I am the successor of Allah's Messenger (ﷺ).' So he (i.e. Abu Bakr) took charge of this property and disposed of it in the same manner as Allah's Messenger (ﷺ) used to do, and all of you (at that time) knew all about it.\" Then `Umar turned towards `Ali and `Abbas and said, \"You both remember that Abu Bakr disposed of it in the way you have described and Allah knows that, in that matter, he was sincere, pious, rightly guided and the follower of the right. Then Allah caused Abu Bakr to die and I said, 'I am the successor of Allah's Messenger (ﷺ) and Abu Bakr.' So I kept this property in my possession for the first two years of my rule (i.e. Caliphate and I used to dispose of it in the same wa as Allah's Messenger (ﷺ) and Abu Bakr used to do; and Allah knows that I have been sincere, pious, rightly guided an the follower of the right (in this matte Later on both of you (i.e. `Ali and `Abbas) came to me, and the claim of you both was one and the same, O `Abbas! You also came to me. So I told you both that Allah's Messenger (ﷺ) said, \"Our property is not inherited, but whatever we leave is to be given in charity.' Then when I thought that I should better hand over this property to you both or the condition that you will promise and pledge before Allah that you will dispose it off in the same way as Allah's Messenger (ﷺ) and Abu Bakr did and as I have done since the beginning of my caliphate or else you should not speak to me (about it).' So, both of you said to me, 'Hand it over to us on this condition.' And on this condition I handed it over to you. Do you want me now to give a decision other than that (decision)? By Allah, with Whose Permission both the sky and the earth stand fast, I will never give any decision other than that (decision) till the Last Hour is established. But if you are unable to manage it (i.e. that property), then return it to me, and I will manage on your behalf.\" The sub-narrator said, \"I told `Urwa bin Az-Zubair of this Hadith and he said, 'Malik bin Aus has told the truth\" I heard `Aisha, the wife of the Prophet (ﷺ) saying, 'The wives of the Prophet (ﷺ) sent `Uthman to Abu Bakr demanding from him their 1/8 of the Fai which Allah had granted to his Apostle. But I used to oppose them and say to them: Will you not fear Allah? Don't you know that the Prophet used to say: Our property is not inherited, but whatever we leave is to be given in charity? The Prophet (ﷺ) mentioned that regarding himself. He added: 'The family of Muhammad can take their sustenance from this property. So the wives of the Prophet (ﷺ) stopped demanding it when I told them of that.' So, this property (of Sadaqa) was in the hands of `Ali who withheld it from `Abbas and overpowered him. Then it came in the hands of Hasan bin `Ali, then in the hands of Husain bin `Ali, and then in the hands of `Ali bin Husain and Hasan bin Hasan, and each of the last two used to manage it in turn, then it came in the hands of Zaid bin Hasan, and it was truly the Sadaqa of Allah's Apostle.\"","ar":"حَدَّثَنَا أَبُو الْيَمَانِ، أَخْبَرَنَا شُعَيْبٌ، عَنِ الزُّهْرِيِّ، قَالَ أَخْبَرَنِي مَالِكُ بْنُ أَوْسِ بْنِ الْحَدَثَانِ النَّصْرِيُّ، أَنَّ عُمَرَ بْنَ الْخَطَّابِ ـ رضى الله عنه ـ دَعَاهُ إِذْ جَاءَهُ حَاجِبُهُ يَرْفَا فَقَالَ هَلْ لَكَ فِي عُثْمَانَ، وَعَبْدِ الرَّحْمَنِ، وَالزُّبَيْرِ وَسَعْدٍ يَسْتَأْذِنُونَ فَقَالَ نَعَمْ، فَأَدْخِلْهُمْ‏.‏ فَلَبِثَ قَلِيلاً، ثُمَّ جَاءَ فَقَالَ هَلْ لَكَ فِي عَبَّاسٍ وَعَلِيٍّ يَسْتَأْذِنَانِ قَالَ نَعَمْ‏.‏ فَلَمَّا دَخَلاَ قَالَ عَبَّاسٌ يَا أَمِيرَ الْمُؤْمِنِينَ، اقْضِ بَيْنِي وَبَيْنَ هَذَا، وَهُمَا يَخْتَصِمَانِ فِي الَّذِي أَفَاءَ اللَّهُ عَلَى رَسُولِهِ صلى الله عليه وسلم مِنْ بَنِي النَّضِيرِ، فَاسْتَبَّ عَلِيٌّ وَعَبَّاسٌ، فَقَالَ الرَّهْطُ يَا أَمِيرَ الْمُؤْمِنِينَ، اقْضِ بَيْنَهُمَا وَأَرِحْ أَحَدَهُمَا مِنَ الآخَرِ‏.‏ فَقَالَ عُمَرُ اتَّئِدُوا، أَنْشُدُكُمْ بِاللَّهِ الَّذِي بِإِذْنِهِ تَقُومُ السَّمَاءُ وَالأَرْضُ، هَلْ تَعْلَمُونَ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏\"‏ لاَ نُورَثُ، مَا تَرَكْنَا صَدَقَةٌ ‏\"‏‏.‏ يُرِيدُ بِذَلِكَ نَفْسَهُ‏.‏ قَالُوا قَدْ قَالَ ذَلِكَ‏.‏ فَأَقْبَلَ عُمَرُ عَلَى عَبَّاسٍ وَعَلِيٍّ فَقَالَ أَنْشُدُكُمَا بِاللَّهِ هَلْ تَعْلَمَانِ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَدْ قَالَ ذَلِكَ قَالاَ نَعَمْ‏.‏ قَالَ فَإِنِّي أُحَدِّثُكُمْ عَنْ هَذَا الأَمْرِ، إِنَّ اللَّهَ سُبْحَانَهُ كَانَ خَصَّ رَسُولَهُ صلى الله عليه وسلم فِي هَذَا الْفَىْءِ بِشَىْءٍ لَمْ يُعْطِهِ أَحَدًا غَيْرَهُ فَقَالَ جَلَّ ذِكْرُهُ ‏{‏وَمَا أَفَاءَ اللَّهُ عَلَى رَسُولِهِ مِنْهُمْ فَمَا أَوْجَفْتُمْ عَلَيْهِ مِنْ خَيْلٍ وَلاَ رِكَابٍ‏}‏ إِلَى قَوْلِهِ ‏{‏قَدِيرٌ‏}‏ فَكَانَتْ هَذِهِ خَالِصَةً لِرَسُولِ اللَّهِ صلى الله عليه وسلم، ثُمَّ وَاللَّهِ مَا احْتَازَهَا دُونَكُمْ، وَلاَ اسْتَأْثَرَهَا عَلَيْكُمْ، لَقَدْ أَعْطَاكُمُوهَا وَقَسَمَهَا فِيكُمْ، حَتَّى بَقِيَ هَذَا الْمَالُ مِنْهَا، فَكَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يُنْفِقُ عَلَى أَهْلِهِ نَفَقَةَ سَنَتِهِمْ مِنْ هَذَا الْمَالِ، ثُمَّ يَأْخُذُ مَا بَقِيَ فَيَجْعَلُهُ مَجْعَلَ مَالِ اللَّهِ، فَعَمِلَ ذَلِكَ رَسُولُ اللَّهِ صلى الله عليه وسلم حَيَاتَهُ، ثُمَّ تُوُفِّيَ النَّبِيُّ صلى الله عليه وسلم فَقَالَ أَبُو بَكْرٍ فَأَنَا وَلِيُّ رَسُولِ اللَّهِ صلى الله عليه وسلم‏.‏ فَقَبَضَهُ أَبُو بَكْرٍ، فَعَمِلَ فِيهِ بِمَا عَمِلَ بِهِ رَسُولُ اللَّهِ صلى الله عليه وسلم وَأَنْتُمْ حِينَئِذٍ‏.‏ فَأَقْبَلَ عَلَى عَلِيٍّ وَعَبَّاسٍ وَقَالَ تَذْكُرَانِ أَنَّ أَبَا بَكْرٍ عَمِلَ فِيهِ كَمَا تَقُولاَنِ، وَاللَّهُ يَعْلَمُ إِنَّهُ فِيهِ لَصَادِقٌ بَارٌّ رَاشِدٌ تَابِعٌ لِلْحَقِّ ثُمَّ تَوَفَّى اللَّهُ أَبَا بَكْرٍ فَقُلْتُ أَنَا وَلِيُّ رَسُولِ اللَّهِ صلى الله عليه وسلم وَأَبِي بَكْرٍ‏.‏ فَقَبَضْتُهُ سَنَتَيْنِ مِنْ إِمَارَتِي أَعْمَلُ فِيهِ بِمَا عَمِلَ رَسُولُ اللَّهِ صلى الله عليه وسلم وَأَبُو بَكْرٍ، وَاللَّهُ يَعْلَمُ أَنِّي فِيهِ صَادِقٌ بَارٌّ رَاشِدٌ تَابِعٌ لِلْحَقِّ، ثُمَّ جِئْتُمَانِي كِلاَكُمَا وَكَلِمَتُكُمَا وَاحِدَةٌ وَأَمْرُكُمَا جَمِيعٌ، فَجِئْتَنِي ـ يَعْنِي عَبَّاسًا ـ فَقُلْتُ لَكُمَا إِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏\"‏ لاَ نُورَثُ، مَا تَرَكْنَا صَدَقَةٌ ‏\"‏‏.‏ فَلَمَّا بَدَا لِي أَنْ أَدْفَعَهُ إِلَيْكُمَا قُلْتُ إِنْ شِئْتُمَا دَفَعْتُهُ إِلَيْكُمَا عَلَى أَنَّ عَلَيْكُمَا عَهْدَ اللَّهِ وَمِيثَاقَهُ لَتَعْمَلاَنِ فِيهِ بِمَا عَمِلَ فِيهِ رَسُولُ اللَّهِ صلى الله عليه وسلم وَأَبُو بَكْرٍ، وَمَا عَمِلْتُ فِيهِ مُذْ وَلِيتُ، وَإِلاَّ فَلاَ تُكَلِّمَانِي، فَقُلْتُمَا ادْفَعْهُ إِلَيْنَا بِذَلِكَ‏.‏ فَدَفَعْتُهُ إِلَيْكُمَا، أَفَتَلْتَمِسَانِ مِنِّي قَضَاءً غَيْرَ ذَلِكَ فَوَاللَّهِ الَّذِي بِإِذْنِهِ تَقُومُ السَّمَاءُ وَالأَرْضُ لاَ أَقْضِي فِيهِ بِقَضَاءٍ غَيْرِ ذَلِكَ حَتَّى تَقُومَ السَّاعَةُ، فَإِنْ عَجَزْتُمَا عَنْهُ، فَادْفَعَا إِلَىَّ فَأَنَا أَكْفِيكُمَاهُ‏.‏ قَالَ فَحَدَّثْتُ هَذَا الْحَدِيثَ، عُرْوَةَ بْنَ الزُّبَيْرِ فَقَالَ صَدَقَ مَالِكُ بْنُ أَوْسٍ، أَنَا سَمِعْتُ عَائِشَةَ ـ رضى الله عنها ـ زَوْجَ النَّبِيِّ صلى الله عليه وسلم تَقُولُ أَرْسَلَ أَزْوَاجُ النَّبِيِّ صلى الله عليه وسلم عُثْمَانَ إِلَى أَبِي بَكْرٍ يَسْأَلْنَهُ ثُمُنَهُنَّ مِمَّا أَفَاءَ اللَّهُ عَلَى رَسُولِهِ صلى الله عليه وسلم، فَكُنْتُ أَنَا أَرُدُّهُنَّ، فَقُلْتُ لَهُنَّ أَلاَ تَتَّقِينَ اللَّهَ، أَلَمْ تَعْلَمْنَ أَنَّ النَّبِيَّ صلى الله عليه وسلم كَانَ يَقُولُ ‏\"‏ لاَ نُورَثُ، مَا تَرَكْنَا صَدَقَةٌ ـ يُرِيدُ بِذَلِكَ نَفْسَهُ ـ إِنَّمَا يَأْكُلُ آلُ مُحَمَّدٍ صلى الله عليه وسلم فِي هَذَا الْمَالِ ‏\"‏‏.‏ فَانْتَهَى أَزْوَاجُ النَّبِيِّ صلى الله عليه وسلم إِلَى مَا أَخْبَرَتْهُنَّ‏.‏ قَالَ فَكَانَتْ هَذِهِ الصَّدَقَةُ بِيَدِ عَلِيٍّ، مَنَعَهَا عَلِيٌّ عَبَّاسًا فَغَلَبَهُ عَلَيْهَا، ثُمَّ كَانَ بِيَدِ حَسَنِ بْنِ عَلِيٍّ، ثُمَّ بِيَدِ حُسَيْنِ بْنِ عَلِيٍّ، ثُمَّ بِيَدِ عَلِيِّ بْنِ حُسَيْنٍ وَحَسَنِ بْنِ حَسَنٍ، كِلاَهُمَا كَانَا يَتَدَاوَلاَنِهَا، ثُمَّ بِيَدِ زَيْدِ بْنِ حَسَنٍ، وَهْىَ صَدَقَةُ رَسُولِ اللَّهِ صلى الله عليه وسلم حَقًّا‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 5358","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-5358","x":"Narrated Malik bin Aus bin Al-Hadathan:\n\nOnce I set out to visit `Umar (bin Al-Khattab). (While I was sitting there with him his gate-keeper, Yarfa, came and said, \"Uthman `AbdurRahman (bin `Auf), Az-Zubair and Sa`d (bin Abi Waqqas) are seeking permission (to meet you).\" `Umar said, \"Yes. So he admitted them and they entered, greeted, and sat down. After a short while Yarfa came again and said to `Umar 'Shall I admit `Ali and `Abbas?\" `Umar said, \"Yes.\" He admitted them and when they entered, they greeted and sat down. `Abbas said, \"O Chief of the Believers! Judge between me and this (`Ali).\" The group, `Uthman and his companions Sa`d, 'O Chief of the Believers! Judge between them and relieve one from the other.\" `Umar said. Wait! I beseech you by Allah, by Whose permission both the Heaven and the Earth stand fast ! Do you know that Allah's Messenger (ﷺ) said. 'We (Apostles) do not bequeath anything to our heirs, but whatever we leave is to be given in charity.' And by that Allah's Messenger (ﷺ)s meant himself?\" The group said, \"He did say so.\" `Umar then turned towards 'All and `Abbas and said. \"I beseech you both by Allah, do you know that Allah's Messenger (ﷺ) said that?\" They said, 'Yes \" `Umar said, \"Now, let me talk to you about this matter. Allah favored His Apostle with something of this property (war booty) which He did not give to anybody else. And Allah said:-- 'And what Allah has bestowed on His Apostle (as Fai Booty) from them for which you made no expedition with either cavalry or camelry... Allah is Able to do all things.' (59.6) So this property was especially granted to Allah's Messenger (ﷺ). But by Allah he neither withheld it from you, nor did he keep it for himself and deprive you of it, but he gave it all to you and distributed it among you till only this remained out of it. And out of this property Allah's Messenger (ﷺ) used to provide his family with their yearly needs, and whatever remained, he would spend where Allah's Property (the revenues of Zakat) used to be spent. Allah's Messenger (ﷺ) kept on acting like this throughout his lifetime. Now I beseech you by Allah, do you know that?\" They said, \"Yes.\" Then `Umar said to `Ali and `Abbas, \"I beseech you by Allah, do you both know that?\" They said, \"Yes.\" `Umar added, \"When Allah had taken His Apostle unto Him, Abu Bakr said, 'I am the successor of Allah's Messenger (ﷺ). So he took charge of that property and did with it the same what Allah's Messenger (ﷺ) used to do, and both of you knew all about it then.\" Then `Umar turned towards `Ali and `Abbas and said, \"You both claim that Abu- Bakr was so-and-so! But Allah knows that he was honest, sincere, pious and right (in that matter). Then Allah caused Abu Bakr to die, and I said, 'I am the successor of Allah's Messenger (ﷺ) and Abu Bakr.' So I kept this property in my possession for the first two years of my rule, and I used to do the same with it as Allah's Messenger (ﷺ) and Abu Bakr used to do. Later both of you (`Ali and `Abbas) came to me with the same claim and the same problem. (O `Abbas!) You came to me demanding your share from (the inheritance of) the son of your brother, and he (`Ali) came to me demanding his wives share from (the inheritance of) her father. So I said to you, 'If you wish I will hand over this property to you, on condition that you both promise me before Allah that you will manage it in the same way as Allah's Messenger (ﷺ) and Abu Bakr did, and as I have done since the beginning of my rule; otherwise you should not speak to me about it.' So you both said, 'Hand over this property to us on this condition.' And on this condition I handed it over to you. I beseech you by Allah, did I hand it over to them on that condition?\" The group said, \"Yes.\" `Umar then faced `Ali and `Abbas and said, \"I beseech you both by Allah, did I hand it over to you both on that condition?\" They both said, \"Yes.\" `Umar added, \"Do you want me now to give a decision other than that? By Him with Whose permission (order) both the Heaven and the Earth stand fast, I will never give any decision other than that till the Hour is established! But if you are unable to manage it (that property), then return it to me and I will be sufficient for it on your behalf. \"","ar":"حَدَّثَنَا سَعِيدُ بْنُ عُفَيْرٍ، قَالَ حَدَّثَنِي اللَّيْثُ، قَالَ حَدَّثَنِي عُقَيْلٌ، عَنِ ابْنِ شِهَابٍ، قَالَ أَخْبَرَنِي مَالِكُ بْنُ أَوْسِ بْنِ الْحَدَثَانِ، وَكَانَ، مُحَمَّدُ بْنُ جُبَيْرِ بْنِ مُطْعِمٍ ذَكَرَ لِي ذِكْرًا مِنْ حَدِيثِهِ، فَانْطَلَقْتُ حَتَّى دَخَلْتُ عَلَى مَالِكِ بْنِ أَوْسٍ فَسَأَلْتُهُ فَقَالَ مَالِكٌ انْطَلَقْتُ حَتَّى أَدْخُلَ عَلَى عُمَرَ، إِذْ أَتَاهُ حَاجِبُهُ يَرْفَا فَقَالَ هَلْ لَكَ فِي عُثْمَانَ وَعَبْدِ الرَّحْمَنِ وَالزُّبَيْرِ وَسَعْدٍ يَسْتَأْذِنُونَ قَالَ نَعَمْ‏.‏ فَأَذِنَ لَهُمْ ـ قَالَ ـ فَدَخَلُوا وَسَلَّمُوا فَجَلَسُوا، ثُمَّ لَبِثَ يَرْفَا قَلِيلاً فَقَالَ لِعُمَرَ هَلْ لَكَ فِي عَلِيٍّ وَعَبَّاسٍ قَالَ نَعَمْ‏.‏ فَأَذِنَ لَهُمَا، فَلَمَّا دَخَلاَ سَلَّمَا وَجَلَسَا، فَقَالَ عَبَّاسٌ يَا أَمِيرَ الْمُؤْمِنِينَ اقْضِ بَيْنِي وَبَيْنَ هَذَا‏.‏ فَقَالَ الرَّهْطُ عُثْمَانُ وَأَصْحَابُهُ يَا أَمِيرَ الْمُؤْمِنِينَ اقْضِ بَيْنَهُمَا، وَأَرِحْ أَحَدَهُمَا مِنَ الآخَرِ‏.‏ فَقَالَ عُمَرُ اتَّئِدُوا أَنْشُدُكُمْ بِاللَّهِ الَّذِي بِهِ تَقُومُ السَّمَاءُ وَالأَرْضُ، هَلْ تَعْلَمُونَ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏\"‏ لاَ نُورَثُ مَا تَرَكْنَا صَدَقَةٌ ‏\"‏‏.‏ يُرِيدُ رَسُولُ اللَّهِ صلى الله عليه وسلم نَفْسَهُ‏.‏ قَالَ الرَّهْطُ قَدْ قَالَ ذَلِكَ‏.‏ فَأَقْبَلَ عُمَرُ عَلَى عَلِيٍّ وَعَبَّاسٍ فَقَالَ أَنْشُدُكُمَا بِاللَّهِ هَلْ تَعْلَمَانِ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ذَلِكَ قَالاَ قَدْ قَالَ ذَلِكَ‏.‏ قَالَ عُمَرُ فَإِنِّي أُحَدِّثُكُمْ عَنْ هَذَا الأَمْرِ، إِنَّ اللَّهَ كَانَ خَصَّ رَسُولَهُ صلى الله عليه وسلم فِي هَذَا الْمَالِ بِشَىْءٍ لَمْ يُعْطِهِ أَحَدًا غَيْرَهُ، قَالَ اللَّهُ ‏{‏مَا أَفَاءَ اللَّهُ عَلَى رَسُولِهِ مِنْهُمْ فَمَا أَوْجَفْتُمْ عَلَيْهِ مِنْ خَيْلٍ‏}‏ إِلَى قَوْلِهِ ‏{‏قَدِيرٌ‏}‏‏.‏ فَكَانَتْ هَذِهِ خَالِصَةً لِرَسُولِ اللَّهِ صلى الله عليه وسلم وَاللَّهِ مَا احْتَازَهَا دُونَكُمْ وَلاَ اسْتَأْثَرَ بِهَا عَلَيْكُمْ، لَقَدْ أَعْطَاكُمُوهَا وَبَثَّهَا فِيكُمْ، حَتَّى بَقِيَ مِنْهَا هَذَا الْمَالُ، فَكَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يُنْفِقُ عَلَى أَهْلِهِ نَفَقَةَ سَنَتِهِمْ مِنْ هَذَا الْمَالِ، ثُمَّ يَأْخُذُ مَا بَقِيَ، فَيَجْعَلُهُ مَجْعَلَ مَالِ اللَّهِ، فَعَمِلَ بِذَلِكَ رَسُولُ اللَّهِ صلى الله عليه وسلم حَيَاتَهُ، أَنْشُدُكُمْ بِاللَّهِ، هَلْ تَعْلَمُونَ ذَلِكَ قَالُوا نَعَمْ‏.‏ قَالَ لِعَلِيٍّ وَعَبَّاسٍ أَنْشُدُكُمَا بِاللَّهِ هَلْ تَعْلَمَانِ ذَلِكَ قَالاَ نَعَمْ‏.‏ ثُمَّ تَوَفَّى اللَّهُ نَبِيَّهُ صلى الله عليه وسلم فَقَالَ أَبُو بَكْرٍ أَنَا وَلِيُّ رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَبَضَهَا أَبُو بَكْرٍ يَعْمَلُ فِيهَا بِمَا عَمِلَ بِهِ فِيهَا رَسُولُ اللَّهِ صلى الله عليه وسلم وَأَنْتُمَا حِينَئِذٍ ـ وَأَقْبَلَ عَلَى عَلِيٍّ وَعَبَّاسٍ ـ تَزْعُمَانِ أَنَّ أَبَا بَكْرٍ كَذَا وَكَذَا، وَاللَّهُ يَعْلَمُ أَنَّهُ فِيهَا صَادِقٌ بَارٌّ رَاشِدٌ تَابِعٌ لِلْحَقِّ، ثُمَّ تَوَفَّى اللَّهُ أَبَا بَكْرٍ فَقُلْتُ أَنَا وَلِيُّ رَسُولِ اللَّهِ صلى الله عليه وسلم وَأَبِي بَكْرٍ، فَقَبَضْتُهَا سَنَتَيْنِ أَعْمَلُ فِيهَا بِمَا عَمِلَ رَسُولُ اللَّهِ صلى الله عليه وسلم وَأَبُو بَكْرٍ، ثُمَّ جِئْتُمَانِي وَكَلِمَتُكُمَا وَاحِدَةٌ وَأَمْرُكُمَا جَمِيعٌ، جِئْتَنِي تَسْأَلُنِي نَصِيبَكَ مِنِ ابْنِ أَخِيكَ، وَأَتَى هَذَا يَسْأَلُنِي نَصِيبَ امْرَأَتِهِ مِنْ أَبِيهَا، فَقُلْتُ إِنْ شِئْتُمَا دَفَعْتُهُ إِلَيْكُمَا عَلَى أَنَّ عَلَيْكُمَا عَهْدَ اللَّهِ وَمِيثَاقَهُ لَتَعْمَلاَنِ فِيهَا بِمَا عَمِلَ بِهِ رَسُولُ اللَّهِ صلى الله عليه وسلم وَبِمَا عَمِلَ بِهِ فِيهَا أَبُو بَكْرٍ، وَبِمَا عَمِلْتُ بِهِ فِيهَا، مُنْذُ وُلِّيتُهَا، وَإِلاَّ فَلاَ تُكَلِّمَانِي فِيهَا فَقُلْتُمَا ادْفَعْهَا إِلَيْنَا بِذَلِكَ‏.‏ فَدَفَعْتُهَا إِلَيْكُمَا بِذَلِكَ، أَنْشُدُكُمْ بِاللَّهِ هَلْ دَفَعْتُهَا إِلَيْهِمَا بِذَلِكَ فَقَالَ الرَّهْطُ نَعَمْ‏.‏ قَالَ فَأَقْبَلَ عَلَى عَلِيٍّ وَعَبَّاسٍ فَقَالَ أَنْشُدُكُمَا بِاللَّهِ هَلْ دَفَعْتُهَا إِلَيْكُمَا بِذَلِكَ قَالاَ نَعَمْ‏.‏ قَالَ أَفَتَلْتَمِسَانِ مِنِّي قَضَاءً غَيْرَ ذَلِكَ، فَوَالَّذِي بِإِذْنِهِ تَقُومُ السَّمَاءُ وَالأَرْضُ لاَ أَقْضِي فِيهَا قَضَاءً غَيْرَ ذَلِكَ، حَتَّى تَقُومَ السَّاعَةُ، فَإِنْ عَجَزْتُمَا عَنْهَا فَادْفَعَاهَا فَأَنَا أَكْفِيكُمَاهَا‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 6728","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-6728","x":"Narrated Malik bin Aus:\n\n'I went and entered upon `Umar, his doorman, Yarfa came saying `Uthman, `Abdur-Rahman, Az- Zubair and Sa`d are asking your permission (to see you). May I admit them? `Umar said, 'Yes.' So he admitted them Then he came again and said, 'May I admit `Ali and `Abbas?' He said, 'Yes.' `Abbas said, 'O, chief of the believers! Judge between me and this man (Ali ). `Umar said, 'I beseech you by Allah by Whose permission both the heaven and the earth exist, do you know that Allah's Messenger (ﷺ) said, 'Our (the Apostles') property will not be inherited, and whatever we leave (after our death) is to be spent in charity?' And by that Allah's Messenger (ﷺ) meant himself.' The group said, '(No doubt), he said so.' `Umar then faced `Ali and `Abbas and said, 'Do you both know that Allah's Messenger (ﷺ) said that?' They replied, '(No doubt), he said so.' `Umar said, 'So let me talk to you about this matter. Allah favored His Apostle with something of this Fai' (i.e. booty won by the Muslims at war without fighting) which He did not give to anybody else; Allah said:-- 'And what Allah gave to His Apostle ( Fai' Booty).........to do all things....(59.6) And so that property was only for Allah's Messenger (ﷺ). Yet, by Allah, he neither gathered that property for himself nor withheld it from you, but he gave its income to you, and distributed it among you till there remained the present property out of which the Prophet (ﷺ) used to spend the yearly maintenance for his family, and whatever used to remain, he used to spend it where Allah's property is spent (i.e. in charity etc.). Allah's Messenger (ﷺ) followed that throughout his life. Now I beseech you by Allah, do you know all that?' They said, 'Yes.' `Umar then said to `Ali and `Abbas, 'I beseech you by Allah, do you know that?' Both of them said, 'Yes.' `Umar added, 'And when the Prophet (ﷺ) died, Abu Bakr said, ' I am the successor of Allah's Messenger (ﷺ), and took charge of that property and managed it in the same way as Allah's Messenger (ﷺ) did. Then I took charge of this property for two years during which I managed it as Allah's Messenger (ﷺ) and Abu Bakr did. Then you both (`Ali and `Abbas) came to talk to me, bearing the same claim and presenting the same case. (O `Abbas!) You came to me asking for your share from the property of your nephew, and this man (Ali) came to me, asking for the share of h is wife from the property of her father. I said, 'If you both wish, I will give that to you on that condition (i.e. that you would follow the way of the Prophet (ﷺ) and Abu Bakr and as I (`Umar) have done in man aging it).' Now both of you seek of me a verdict other than that? Lo! By Allah, by Whose permission both the heaven and the earth exist, I will not give any verdict other than that till the Hour is established. If you are unable to manage it, then return it to me, and I will be sufficient to manage it on your behalf.' \"","ar":"حَدَّثَنَا يَحْيَى بْنُ بُكَيْرٍ، حَدَّثَنَا اللَّيْثُ، عَنْ عُقَيْلٍ، عَنِ ابْنِ شِهَابٍ، قَالَ أَخْبَرَنِي مَالِكُ بْنُ أَوْسِ بْنِ الْحَدَثَانِ،، وَكَانَ، مُحَمَّدُ بْنُ جُبَيْرِ بْنِ مُطْعِمٍ ذَكَرَ لِي مِنْ حَدِيثِهِ ذَلِكَ، فَانْطَلَقْتُ حَتَّى دَخَلْتُ عَلَيْهِ فَسَأَلْتُهُ فَقَالَ انْطَلَقْتُ حَتَّى أَدْخُلَ عَلَى عُمَرَ فَأَتَاهُ حَاجِبُهُ يَرْفَأُ فَقَالَ هَلْ لَكَ فِي عُثْمَانَ وَعَبْدِ الرَّحْمَنِ وَالزُّبَيْرِ وَسَعْدٍ قَالَ نَعَمْ‏.‏ فَأَذِنَ لَهُمْ، ثُمَّ قَالَ هَلْ لَكَ فِي عَلِيٍّ وَعَبَّاسٍ قَالَ نَعَمْ‏.‏ قَالَ عَبَّاسٌ يَا أَمِيرَ الْمُؤْمِنِينَ اقْضِ بَيْنِي وَبَيْنَ هَذَا‏.‏ قَالَ أَنْشُدُكُمْ بِاللَّهِ الَّذِي بِإِذْنِهِ تَقُومُ السَّمَاءُ وَالأَرْضُ هَلْ تَعْلَمُونَ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏\"‏ لاَ نُورَثُ مَا تَرَكْنَا صَدَقَةٌ ‏\"‏‏.‏ يُرِيدُ رَسُولُ اللَّهِ صلى الله عليه وسلم نَفْسَهُ‏.‏ فَقَالَ الرَّهْطُ قَدْ قَالَ ذَلِكَ‏.‏ فَأَقْبَلَ عَلَى عَلِيٍّ وَعَبَّاسٍ فَقَالَ هَلْ تَعْلَمَانِ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ذَلِكَ قَالاَ قَدْ قَالَ ذَلِكَ‏.‏ قَالَ عُمَرُ فَإِنِّي أُحَدِّثُكُمْ عَنْ هَذَا الأَمْرِ، إِنَّ اللَّهَ قَدْ كَانَ خَصَّ رَسُولَهُ صلى الله عليه وسلم فِي هَذَا الْفَىْءِ بِشَىْءٍ لَمْ يُعْطِهِ أَحَدًا غَيْرَهُ، فَقَالَ عَزَّ وَجَلَّ ‏{‏مَا أَفَاءَ اللَّهُ عَلَى رَسُولِهِ‏}‏ إِلَى قَوْلِهِ ‏{‏قَدِيرٌ‏}‏ فَكَانَتْ خَالِصَةً لِرَسُولِ اللَّهِ صلى الله عليه وسلم وَاللَّهِ مَا احْتَازَهَا دُونَكُمْ، وَلاَ اسْتَأْثَرَ بِهَا عَلَيْكُمْ، لَقَدْ أَعْطَاكُمُوهُ وَبَثَّهَا فِيكُمْ، حَتَّى بَقِيَ مِنْهَا هَذَا الْمَالُ، فَكَانَ النَّبِيُّ صلى الله عليه وسلم يُنْفِقُ عَلَى أَهْلِهِ مِنْ هَذَا الْمَالِ نَفَقَةَ سَنَتِهِ، ثُمَّ يَأْخُذُ مَا بَقِيَ فَيَجْعَلُهُ مَجْعَلَ مَالِ اللَّهِ، فَعَمِلَ بِذَلِكَ رَسُولُ اللَّهِ صلى الله عليه وسلم حَيَاتَهُ، أَنْشُدُكُمْ بِاللَّهِ هَلْ تَعْلَمُونَ ذَلِكَ قَالُوا نَعَمْ‏.‏ ثُمَّ قَالَ لِعَلِيٍّ وَعَبَّاسٍ أَنْشُدُكُمَا بِاللَّهِ هَلْ تَعْلَمَانِ ذَلِكَ قَالاَ نَعَمْ‏.‏ فَتَوَفَّى اللَّهُ نَبِيَّهُ صلى الله عليه وسلم فَقَالَ أَبُو بَكْرٍ أَنَا وَلِيُّ رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَبَضَهَا فَعَمِلَ بِمَا عَمِلَ بِهِ رَسُولُ اللَّهِ صلى الله عليه وسلم ثُمَّ تَوَفَّى اللَّهُ أَبَا بَكْرٍ فَقُلْتُ أَنَا وَلِيُّ وَلِيِّ رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَبَضْتُهَا سَنَتَيْنِ أَعْمَلُ فِيهَا مَا عَمِلَ رَسُولُ اللَّهِ صلى الله عليه وسلم وَأَبُو بَكْرٍ، ثُمَّ جِئْتُمَانِي وَكَلِمَتُكُمَا وَاحِدَةٌ، وَأَمْرُكُمَا جَمِيعٌ، جِئْتَنِي تَسْأَلُنِي نَصِيبَكَ مِنِ ابْنِ أَخِيكَ، وَأَتَانِي هَذَا يَسْأَلُنِي نَصِيبَ امْرَأَتِهِ مِنْ أَبِيهَا فَقُلْتُ إِنْ شِئْتُمَا دَفَعْتُهَا إِلَيْكُمَا بِذَلِكَ، فَتَلْتَمِسَانِ مِنِّي قَضَاءً غَيْرَ ذَلِكَ، فَوَاللَّهِ الَّذِي بِإِذْنِهِ تَقُومُ السَّمَاءُ وَالأَرْضُ، لاَ أَقْضِي فِيهَا قَضَاءً غَيْرَ ذَلِكَ حَتَّى تَقُومَ السَّاعَةُ، فَإِنْ عَجَزْتُمَا فَادْفَعَاهَا إِلَىَّ، فَأَنَا أَكْفِيكُمَاهَا‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 7305","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-7305","x":"Narrated Malik bin Aus An-Nasri:\n\nI proceeded till I entered upon `Umar (and while I was sitting there), his gate-keeper Yarfa came to him and said, \" `Uthman, `Abdur-Rahman, Az-Zubair and Sa`d ask your permission to come in.\" `Umar allowed them. So they entered, greeted, and sat down. (After a while the gatekeeper came) and said, \"Shall I admit `Ali and `Abbas?'' `Umar allowed them to enter. Al-`Abbas said \"O Chief of the believers! Judge between me and the oppressor (`Ali).\" Then there was a dispute (regarding the property of Bani Nadir) between them (`Abbas and `Ali). `Uthman and his companions said, \"O Chief of the Believers! Judge between them and relieve one from the other.\" `Umar said, \"Be patient! beseech you by Allah, with Whose permission the Heaven and the Earth Exist! Do you know that Allah's Messenger (ﷺ) said, 'Our property is not to be inherited, and whatever we leave is to be given in charity,' and by this Allah's Messenger (ﷺ) meant himself?\" On that the group said, \"He verily said so.\" `Umar then faced `Ali and `Abbas and said, \"I beseech you both by Allah, do you both know that Allah's Messenger (ﷺ) said so?\" They both replied, \"Yes\". `Umar then said, \"Now I am talking to you about this matter (in detail). Allah favored Allah's Messenger (ﷺ) with some of this wealth which He did not give to anybody else, as Allah said: 'What Allah bestowed as Fai (Booty on His Apostle for which you made no expedition... ' (59.6) So that property was totally meant for Allah's Messenger (ﷺ), yet he did not collect it and ignore you, nor did he withhold it with your exclusion, but he gave it to you and distributed it among you till this much of it was left behind, and the Prophet, used to spend of this as the yearly expenditures of his family and then take what remained of it and spent it as he did with (other) Allah's wealth. The Prophet (ﷺ) did so during all his lifetime, and I beseech you by Allah, do you know that?\" They replied, \"Yes.\" `Umar then addressed `Ali and `Abbas, saying, \"I beseech you both by Allah, do you know that?\" Both of them replied, \"Yes.\" `Umar added, \"Then Allah took His Apostle unto Him. Abu Bakr then said 'I am the successor of Allah's Messenger (ﷺ)' and took over all the Prophet's property and disposed of it in the same way as Allah's Messenger (ﷺ) used to do, and you were present then.\" Then he turned to `Ali and `Abbas and said, \"You both claim that Abu Bakr did so-and-so in managing the property, but Allah knows that Abu Bakr was honest, righteous, intelligent, and a follower of what is right in managing it. Then Allah took Abu Bakr unto Him, 'I said: I am the successor of Allah's Messenger (ﷺ) and Abu Bakr.' So I took over the property for two years and managed it in the same way as Allah's Messenger (ﷺ), and Abu Bakr used to do. Then you both (`Ali and `Abbas) came to me and asked for the same thing! (O `Abbas! You came to me to ask me for your share from nephew's property; and this (`Ali) came to me asking for his wives share from her father's property, and I said to you both, 'If you wish, I will place it in your custody on condition that you both will manage it in the same way as Allah's Messenger (ﷺ) and Abu Bakr did and as I have been doing since I took charge of managing it; otherwise, do not speak to me anymore about it.' Then you both said, 'Give it to us on that (condition).' So I gave it to you on that condition. Now I beseech you by Allah, did I not give it to them on that condition?\" The group (whom he had been addressing) replied, \"Yes.\" `Umar then addressed `Abbas and `Ali saying, \"I beseech you both by Allah, didn't I give you all that property on that condition?\" They said, \"Yes.\" `Umar then said, \"Are you now seeking a verdict from me other than that? By Him with Whose Permission the Heaven and the Earth exists I will not give any verdict other than that till the Hour is established; and if you both are unable to manage this property, then you can hand it back to me, and I will be sufficient for it on your behalf.\" (See, Hadith No. 326, Vol. 4)","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ يُوسُفَ، حَدَّثَنَا اللَّيْثُ، حَدَّثَنِي عُقَيْلٌ، عَنِ ابْنِ شِهَابٍ، قَالَ أَخْبَرَنِي مَالِكُ بْنُ أَوْسٍ النَّصْرِيُّ، وَكَانَ، مُحَمَّدُ بْنُ جُبَيْرِ بْنِ مُطْعِمٍ ذَكَرَ لِي ذِكْرًا مِنْ ذَلِكَ فَدَخَلْتُ عَلَى مَالِكٍ فَسَأَلْتُهُ فَقَالَ انْطَلَقْتُ حَتَّى أَدْخُلَ عَلَى عُمَرَ أَتَاهُ حَاجِبُهُ يَرْفَا فَقَالَ هَلْ لَكَ فِي عُثْمَانَ وَعَبْدِ الرَّحْمَنِ وَالزُّبَيْرِ وَسَعْدٍ يَسْتَأْذِنُونَ‏.‏ قَالَ نَعَمْ‏.‏ فَدَخَلُوا فَسَلَّمُوا وَجَلَسُوا‏.‏ فَقَالَ هَلْ لَكَ فِي عَلِيٍّ وَعَبَّاسٍ‏.‏ فَأَذِنَ لَهُمَا‏.‏ قَالَ الْعَبَّاسُ يَا أَمِيرَ الْمُؤْمِنِينَ اقْضِ بَيْنِي وَبَيْنَ الظَّالِمِ‏.‏ اسْتَبَّا‏.‏ فَقَالَ الرَّهْطُ عُثْمَانُ وَأَصْحَابُهُ يَا أَمِيرَ الْمُؤْمِنِينَ اقْضِ بَيْنَهُمَا وَأَرِحْ أَحَدَهُمَا مِنَ الآخَرِ‏.‏ فَقَالَ اتَّئِدُوا أَنْشُدُكُمْ بِاللَّهِ الَّذِي بِإِذْنِهِ تَقُومُ السَّمَاءُ وَالأَرْضُ، هَلْ تَعْلَمُونَ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏\"‏ لاَ نُورَثُ مَا تَرَكْنَا صَدَقَةٌ ‏\"‏‏.‏ يُرِيدُ رَسُولُ اللَّهِ صلى الله عليه وسلم نَفْسَهُ‏.‏ قَالَ الرَّهْطُ قَدْ قَالَ ذَلِكَ‏.‏ فَأَقْبَلَ عُمَرُ عَلَى عَلِيٍّ وَعَبَّاسٍ فَقَالَ أَنْشُدُكُمَا بِاللَّهِ هَلْ تَعْلَمَانِ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ذَلِكَ‏.‏ قَالاَ نَعَمْ‏.‏ قَالَ عُمَرُ فَإِنِّي مُحَدِّثُكُمْ عَنْ هَذَا الأَمْرِ، إِنَّ اللَّهَ كَانَ خَصَّ رَسُولَهُ صلى الله عليه وسلم فِي هَذَا الْمَالِ بِشَىْءٍ لَمْ يُعْطِهِ أَحَدًا غَيْرَهُ، فَإِنَّ اللَّهَ يَقُولُ ‏{‏مَا أَفَاءَ اللَّهُ عَلَى رَسُولِهِ مِنْهُمْ فَمَا أَوْجَفْتُمْ‏}‏ الآيَةَ، فَكَانَتْ هَذِهِ خَالِصَةً لِرَسُولِ اللَّهِ صلى الله عليه وسلم، ثُمَّ وَاللَّهِ مَا احْتَازَهَا دُونَكُمْ وَلاَ اسْتَأْثَرَ بِهَا عَلَيْكُمْ، وَقَدْ أَعْطَاكُمُوهَا وَبَثَّهَا فِيكُمْ، حَتَّى بَقِيَ مِنْهَا هَذَا الْمَالُ، وَكَانَ النَّبِيُّ صلى الله عليه وسلم يُنْفِقُ عَلَى أَهْلِهِ نَفَقَةَ سَنَتِهِمْ مِنْ هَذَا الْمَالِ، ثُمَّ يَأْخُذُ مَا بَقِيَ فَيَجْعَلُهُ مَجْعَلَ مَالِ اللَّهِ، فَعَمِلَ النَّبِيُّ صلى الله عليه وسلم بِذَلِكَ حَيَاتَهُ، أَنْشُدُكُمْ بِاللَّهِ هَلْ تَعْلَمُونَ ذَلِكَ فَقَالُوا نَعَمْ‏.‏ ثُمَّ قَالَ لِعَلِيٍّ وَعَبَّاسٍ أَنْشُدُكُمَا اللَّهَ هَلْ تَعْلَمَانِ ذَلِكَ قَالاَ نَعَمْ‏.‏ ثُمَّ تَوَفَّى اللَّهُ نَبِيَّهُ صلى الله عليه وسلم فَقَالَ أَبُو بَكْرٍ أَنَا وَلِيُّ رَسُولِ اللَّهِ صلى الله عليه وسلم، فَقَبَضَهَا أَبُو بَكْرٍ فَعَمِلَ فِيهَا بِمَا عَمِلَ فِيهَا رَسُولُ اللَّهِ صلى الله عليه وسلم، وَأَنْتُمَا حِينَئِذٍ ـ وَأَقْبَلَ عَلَى عَلِيٍّ وَعَبَّاسٍ ـ تَزْعُمَانِ أَنَّ أَبَا بَكْرٍ فِيهَا كَذَا، وَاللَّهُ يَعْلَمُ أَنَّهُ فِيهَا صَادِقٌ بَارٌّ رَاشِدٌ تَابِعٌ لِلْحَقِّ، ثُمَّ تَوَفَّى اللَّهُ أَبَا بَكْرٍ فَقُلْتُ أَنَا وَلِيُّ رَسُولِ اللَّهِ صلى الله عليه وسلم وَأَبِي بَكْرٍ‏.‏ فَقَبَضْتُهَا سَنَتَيْنِ أَعْمَلُ فِيهَا بِمَا عَمِلَ بِهِ رَسُولُ اللَّهِ صلى الله عليه وسلم وَأَبُو بَكْرٍ، ثُمَّ جِئْتُمَانِي وَكَلِمَتُكُمَا عَلَى كَلِمَةٍ وَاحِدَةٍ وَأَمْرُكُمَا جَمِيعٌ، جِئْتَنِي تَسْأَلُنِي نَصِيبَكَ مِنِ ابْنِ أَخِيكَ، وَأَتَانِي هَذَا يَسْأَلُنِي نَصِيبَ امْرَأَتِهِ مِنْ أَبِيهَا فَقُلْتُ إِنْ شِئْتُمَا دَفَعْتُهَا إِلَيْكُمَا، عَلَى أَنَّ عَلَيْكُمَا عَهْدَ اللَّهِ وَمِيثَاقَهُ تَعْمَلاَنِ فِيهَا بِمَا عَمِلَ بِهِ رَسُولُ اللَّهِ صلى الله عليه وسلم وَبِمَا عَمِلَ فِيهَا أَبُو بَكْرٍ وَبِمَا عَمِلْتُ فِيهَا مُنْذُ وَلِيتُهَا، وَإِلاَّ فَلاَ تُكَلِّمَانِي فِيهَا‏.‏ فَقُلْتُمَا ادْفَعْهَا إِلَيْنَا بِذَلِكَ‏.‏ فَدَفَعْتُهَا إِلَيْكُمَا بِذَلِكَ، أَنْشُدُكُمْ بِاللَّهِ هَلْ دَفَعْتُهَا إِلَيْهِمَا بِذَلِكَ قَالَ الرَّهْطُ نَعَمْ‏.‏ فَأَقْبَلَ عَلَى عَلِيٍّ وَعَبَّاسٍ فَقَالَ أَنْشُدُكُمَا بِاللَّهِ هَلْ دَفَعْتُهَا إِلَيْكُمَا بِذَلِكَ‏.‏ قَالاَ نَعَمْ‏.‏ قَالَ أَفَتَلْتَمِسَانِ مِنِّي قَضَاءً غَيْرَ ذَلِكَ فَوَالَّذِي بِإِذْنِهِ تَقُومُ السَّمَاءُ وَالأَرْضُ لاَ أَقْضِي فِيهَا قَضَاءً غَيْرَ ذَلِكَ حَتَّى تَقُومَ السَّاعَةُ، فَإِنْ عَجَزْتُمَا عَنْهَا فَادْفَعَاهَا إِلَىَّ، فَأَنَا أَكْفِيكُمَاهَا‏.‏","v":[]}],"7":[{"c":"Sahih Bukhari","r":"Hadith 4886","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4886","x":"Narrated Alqama:\n\n`Abdullah (bin Masud) said. \"Allah curses those ladies who practice tattooing and those who get themselves tattooed, and those ladies who remove the hair from their faces and those who make artificial spaces between their teeth in order to look more beautiful whereby they change Allah's creation.\" His saying reached a lady from Bani Asd called Um Yaqub who came (to `Abdullah) and said, \"I have come to know that you have cursed such-and-such (ladies)?\" He replied, \"Why should I not curse these whom Allah's Messenger (ﷺ) has cursed and who are (cursed) in Allah's Book!\" Um Yaqub said, \"I have read the whole Qur'an, but I did not find in it what you say.\" He said, \"Verily, if you have read it (i.e. the Qur'an), you have found it. Didn't you read: 'And whatsoever the Apostle gives you take it and whatsoever he forbids you, you abstain (from it). (59.7) She replied, \"Yes, I did,\" He said, \"Verily, Allah's Messenger (ﷺ) forbade such things.\" \"She said, \"But I see your wife doing these things?\" He said, \"Go and watch her.\" She went and watched her but could not see anything in support of her statement. On that he said, \"If my wife was as you thought, I would not keep her in my company.\"","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ يُوسُفَ، حَدَّثَنَا سُفْيَانُ، عَنْ مَنْصُورٍ، عَنْ إِبْرَاهِيمَ، عَنْ عَلْقَمَةَ، عَنْ عَبْدِ اللَّهِ، قَالَ لَعَنَ اللَّهُ الْوَاشِمَاتِ وَالْمُوتَشِمَاتِ وَالْمُتَنَمِّصَاتِ وَالْمُتَفَلِّجَاتِ لِلْحُسْنِ الْمُغَيِّرَاتِ خَلْقَ اللَّهِ‏.‏ فَبَلَغَ ذَلِكَ امْرَأَةً مِنْ بَنِي أَسَدٍ يُقَالُ لَهَا أُمُّ يَعْقُوبَ، فَجَاءَتْ فَقَالَتْ إِنَّهُ بَلَغَنِي أَنَّكَ لَعَنْتَ كَيْتَ وَكَيْتَ‏.‏ فَقَالَ وَمَا لِي لاَ أَلْعَنُ مَنْ لَعَنَ رَسُولُ اللَّهِ صلى الله عليه وسلم وَمَنْ هُوَ فِي كِتَابِ اللَّهِ فَقَالَتْ لَقَدْ قَرَأْتُ مَا بَيْنَ اللَّوْحَيْنِ فَمَا وَجَدْتُ فِيهِ مَا تَقُولُ‏.‏ قَالَ لَئِنْ كُنْتِ قَرَأْتِيهِ لَقَدْ وَجَدْتِيهِ، أَمَا قَرَأْتِ ‏{‏وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا‏}‏‏.‏ قَالَتْ بَلَى‏.‏ قَالَ فَإِنَّهُ قَدْ نَهَى عَنْهُ‏.‏ قَالَتْ فَإِنِّي أَرَى أَهْلَكَ يَفْعَلُونَهُ‏.‏ قَالَ فَاذْهَبِي فَانْظُرِي‏.‏ فَذَهَبَتْ فَنَظَرَتْ فَلَمْ تَرَ مِنْ حَاجَتِهَا شَيْئًا، فَقَالَ لَوْ كَانَتْ كَذَلِكَ مَا جَامَعْتُها.","v":[]},{"c":"Sahih Bukhari","r":"Hadith 5931","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-5931","x":"Narrated `Abdullah:\n\nAllah has cursed those women who practise tattooing and those who get themselves tattooed, and those who remove their face hairs, and those who create a space between their teeth artificially to look beautiful, and such women as change the features created by Allah. Why then should I not curse those whom the Prophet (ﷺ) has cursed? And that is in Allah's Book. i.e. His Saying: 'And what the Apostle gives you take it and what he forbids you abstain (from it).' (59.7)","ar":"حَدَّثَنَا عُثْمَانُ، حَدَّثَنَا جَرِيرٌ، عَنْ مَنْصُورٍ، عَنْ إِبْرَاهِيمَ، عَنْ عَلْقَمَةَ، عَنْ عَبْدِ اللَّهِ، لَعَنَ اللَّهُ الْوَاشِمَاتِ، وَالْمُسْتَوْشِمَاتِ، وَالْمُتَنَمِّصَاتِ وَالْمُتَفَلِّجَاتِ لِلْحُسْنِ، الْمُغَيِّرَاتِ خَلْقَ اللَّهِ تَعَالَى، مَالِي لاَ أَلْعَنُ مَنْ لَعَنَ النَّبِيُّ صلى الله عليه وسلم وَهْوَ فِي كِتَابِ اللَّهِ ‏{‏وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ‏}‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 5939","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-5939","x":"Narrated 'Alqama:\n\n`Abdullah cursed those women who practiced tattooing and those who removed hair from their faces and those who created spaces between their teeth artificially to look beautiful, such ladies as changed what Allah has created. Um Ya'qub said, \"What is that?\" `Abdullah said, \"Why should I not curse those who were cursed by Allah's Messenger (ﷺ) and are referred to in Allah's Book?\" She said to him \"By Allah, I have read the whole Qur'an but I have not found such a thing. `Abdullah said, \"By Allah, if you had read it (carefully) you would have found it. (Allah says:) 'And what the Apostle gives you take it and what he forbids you abstain (from it).' (59.7)","ar":"حَدَّثَنَا إِسْحَاقُ بْنُ إِبْرَاهِيمَ، أَخْبَرَنَا جَرِيرٌ، عَنْ مَنْصُورٍ، عَنْ إِبْرَاهِيمَ، عَنْ عَلْقَمَةَ، قَالَ لَعَنَ عَبْدُ اللَّهِ الْوَاشِمَاتِ، وَالْمُتَنَمِّصَاتِ، وَالْمُتَفَلِّجَاتِ لِلْحُسْنِ، الْمُغَيِّرَاتِ خَلْقَ اللَّهِ‏.‏ فَقَالَتْ أُمُّ يَعْقُوبَ مَا هَذَا قَالَ عَبْدُ اللَّهِ وَمَا لِيَ لاَ أَلْعَنُ مَنْ لَعَنَ رَسُولُ اللَّهِ، وَفِي كِتَابِ اللَّهِ‏.‏ قَالَتْ وَاللَّهِ لَقَدْ قَرَأْتُ مَا بَيْنَ اللَّوْحَيْنِ فَمَا وَجَدْتُهُ‏.‏ قَالَ وَاللَّهِ لَئِنْ قَرَأْتِيهِ لَقَدْ وَجَدْتِيهِ ‏{‏وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا‏}‏‏.‏","v":[]},{"c":"Riyad as-Salihin","r":"Hadith 1646","u":"https://quranx.com/Hadith/Saliheen/Reference/Hadith-1646","x":"Ibn Mas'ud (May Allah be pleased with him) said:\n\nAllah has cursed those women who practise tattooing and those women who have themselves tattooed, and those women who get their hair removed from their eyebrows and faces (except the beard and the mustache), and those who make artificial spaces between their teeth for beauty, whereby they change Allah's creation. A woman started to argue with him, saying: \"What is all this?\" He replied: \"Why should I not curse those whom the Messenger of Allah (ﷺ) cursed and who are cursed in Allah's Book? Allah, the Exalted, has said in His Book:\"And whatsoever the Messenger (Muhammad (ﷺ)) gives you, take it; and whatsoever he forbids you, abstain (from it).\" (59:7)[Al-Bukhari and Muslim].","ar":"وعن ابن مسعود رضي الله عنه قال‏:‏ لعن الله الواشمات والمستوشمات والمتنمصات والمتفلجات بالحسن، المغيرات خلق الله‏!‏ فقالت له امرأة في ذلك فقال‏:‏ وما لي لا ألعن من لعنه رسول الله صلى الله عليه وسلم وهو في كتاب الله‏؟‏‏!‏ قال الله تعالى‏:‏ ‏{‏وما آتاكم الرسول فخذوه وما نهاكم عنه فانتهوا‏}‏ ‏(‏‏(‏الحشر‏:‏7‏)‏‏)‏‏.‏‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ المتفلجة هي: التي تبرد من أسنانها ليتباعد بعضها من بعض قليلا، وتحسنها وهو الوشر. والنامصة: [هي] التي تأخذ من شعر حاجب غيرها، وترققه ليصير حسنا. والمتنمصة: التي تأمر من يفعل بها ذلك.","v":[]}],"9":[{"c":"Al-Adab Al-Mufrad","r":"Book 31, Hadith 740","u":"https://quranx.com/Hadith/Adab/English/Book-31/Hadith-740","x":"Abu Hurayrah (ra) said that a man came to the Messenger of Allah (ﷺ). He sent message to his homes that they should send him if they had anything (to entertain his guest). They all sent back a reply that they had nothing but water. The messenger of Allah ^ asked (his companions),\" Who will entertain this guest?\" One of the Ansar volunteered to serve the guest. This companion took him and said to his wife,\" Honour the guest of the Messenger of Allah.\" She responded that they only had the food of their children and nothing more. He said to her,\" Prepare to serve and set the lantern and send the children to sleep\". When they decided to have their meal, she laid the food on the cloth and set the lantern after putting her children to sleep. She then stood pretending to set right the lantern but, in the process, she extinguished it. Both husband and wife sat down leaving an impression on their guest that they were partaking the meal with him. Both of them passed the night in hunger. In the morning, that companion went to the Prophet (ﷺ) who said to him,\" Allah is pleased with your deed and revealed to me this verse:\n\n\"... but give [them] preference over themselves, even though they are in privation. And whoever is protected from the stinginess of his soul - it is those who will be the successful.\" (al-Hashr,59:9)","ar":"حَدَّثَنَا مُسَدَّدٌ، قَالَ‏:‏ حَدَّثَنَا عَبْدُ اللهِ بْنُ دَاوُدَ، عَنْ فُضَيْلِ بْنِ غَزْوَانَ، عَنْ أَبِي حَازِمٍ، عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَجُلاً أَتَى النَّبِيَّ صلى الله عليه وسلم، فَبَعَثَ إِلَى نِسَائِهِ، فَقُلْنَ‏:‏ مَا مَعَنَا إِلاَّ الْمَاءُ، فَقَالَ رَسُولُ اللهِ صلى الله عليه وسلم‏:‏ مَنْ يَضُمُّ، أَوْ يُضِيفُ، هَذَا‏؟‏ فَقَالَ رَجُلٌ مِنَ الأَنْصَارِ‏:‏ أَنَا‏.‏ فَانْطَلَقَ بِهِ إِلَى امْرَأَتِهِ فَقَالَ‏:‏ أَكْرِمِي ضَيْفَ رَسُولِ اللهِ صلى الله عليه وسلم، فَقَالَتْ‏:‏ مَا عِنْدَنَا إِلاَّ قُوتٌ لِلصِّبْيَانِ، فَقَالَ‏:‏ هَيِّئِي طَعَامَكِ، وَأَصْلِحِي سِرَاجَكِ، وَنَوِّمِي صِبْيَانَكِ إِذَا أَرَادُوا عَشَاءً، فَهَيَّأَتْ طَعَامَهَا، وَأَصْلَحَتْ سِرَاجَهَا، وَنَوَّمَتْ صِبْيَانَهَا، ثُمَّ قَامَتْ كَأَنَّهَا تُصْلِحُ سِرَاجَهَا فَأَطْفَأَتْهُ، وَجَعَلاَ يُرِيَانِهِ أَنَّهُمَا يَأْكُلاَنِ، وَبَاتَا طَاوِيَيْنِ، فَلَمَّا أَصْبَحَ غَدَا إِلَى رَسُولِ اللهِ صلى الله عليه وسلم، فَقَالَ صلى الله عليه وسلم‏:‏ لَقَدْ ضَحِكَ اللَّهُ، أَوْ‏:‏ عَجِبَ، مِنْ فَعَالِكُمَا، وَأَنْزَلَ اللَّهُ‏:‏ ‏{‏وَيُؤْثِرُونَ عَلَى أَنْفُسِهِمْ وَلَوْ كَانَ بِهِمْ خَصَاصَةٌ وَمَنْ يُوقَ شُحَّ نَفْسِهِ فَأُولَئِكَ هُمُ الْمُفْلِحُونَ‏}‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 3798","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-3798","x":"Narrated Abu Huraira:\n\nA man came to the Prophet. The Prophet (ﷺ) sent a messenger to his wives (to bring something for that man to eat) but they said that they had nothing except water. Then Allah's Messenger (ﷺ) said, \"Who will take this (person) or entertain him as a guest?\" An Ansar man said, \"I.\" So he took him to his wife and said to her, \"Entertain generously the guest of Allah's Messenger (ﷺ) \" She said, \"We have got nothing except the meals of my children.\" He said, \"Prepare your meal, light your lamp and let your children sleep if they ask for supper.\" So she prepared her meal, lighted her lamp and made her children sleep, and then stood up pretending to mend her lamp, but she put it off. Then both of them pretended to be eating, but they really went to bed hungry. In the morning the Ansari went to Allah's Messenger (ﷺ) who said, \"Tonight Allah laughed or wondered at your action.\" Then Allah revealed: \"But give them (emigrants) preference over themselves even though they were in need of that And whosoever is saved from the covetousness Such are they who will be successful.\" (59.9)","ar":"حَدَّثَنَا مُسَدَّدٌ، حَدَّثَنَا عَبْدُ اللَّهِ بْنُ دَاوُدَ، عَنْ فُضَيْلِ بْنِ غَزْوَانَ، عَنْ أَبِي حَازِمٍ، عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ أَنَّ رَجُلاً، أَتَى النَّبِيَّ صلى الله عليه وسلم فَبَعَثَ إِلَى نِسَائِهِ فَقُلْنَ مَا مَعَنَا إِلاَّ الْمَاءُ‏.‏ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ مَنْ يَضُمُّ، أَوْ يُضِيفُ هَذَا ‏\"‏‏.‏ فَقَالَ رَجُلٌ مِنَ الأَنْصَارِ أَنَا‏.‏ فَانْطَلَقَ بِهِ إِلَى امْرَأَتِهِ، فَقَالَ أَكْرِمِي ضَيْفَ رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَالَتْ مَا عِنْدَنَا إِلاَّ قُوتُ صِبْيَانِي‏.‏ فَقَالَ هَيِّئِي طَعَامَكِ، وَأَصْبِحِي سِرَاجَكِ، وَنَوِّمِي صِبْيَانَكِ إِذَا أَرَادُوا عَشَاءً‏.‏ فَهَيَّأَتْ طَعَامَهَا وَأَصْبَحَتْ سِرَاجَهَا، وَنَوَّمَتْ صِبْيَانَهَا، ثُمَّ قَامَتْ كَأَنَّهَا تُصْلِحُ سِرَاجَهَا فَأَطْفَأَتْهُ، فَجَعَلاَ يُرِيَانِهِ أَنَّهُمَا يَأْكُلاَنِ، فَبَاتَا طَاوِيَيْنِ، فَلَمَّا أَصْبَحَ، غَدَا إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَالَ ‏\"‏ ضَحِكَ اللَّهُ اللَّيْلَةَ ـ أَوْ عَجِبَ ـ مِنْ فَعَالِكُمَا ‏\"‏ فَأَنْزَلَ اللَّهُ ‏{‏وَيُؤْثِرُونَ عَلَى أَنْفُسِهِمْ وَلَوْ كَانَ بِهِمْ خَصَاصَةٌ وَمَنْ يُوقَ شُحَّ نَفْسِهِ فَأُولَئِكَ هُمُ الْمُفْلِحُونَ‏}‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4889","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4889","x":"Narrated Abu Huraira:\n\nA man came to Allah's Messenger (ﷺ) and said, \"O Allah's Messenger (ﷺ)! I am suffering from fatigue and hunger.\" The Prophet (ﷺ) sent (somebody) to his wives (to get something), but the messenger found nothing with them. Then Allah's Messenger (ﷺ) said (to his companions). \"Isn't there anybody who can entertain this man tonight so that Allah may be merciful to him?\" An Ansari man got up and said, \"I (will, entertain him), O Allah's Messenger (ﷺ)!\" So he went to his wife and said to her, \"This is the guest of Allah's Messenger (ﷺ), so do not keep anything away from him.\" She said. \"By Allah, I have nothing but the children's food.\" He said, \"When the children ask for their dinner, put them to bed and put out the light; we shall not take our meals tonight,\" She did so. In the morning the Ansari man went to Allah's Messenger (ﷺ) who said, \"Allah was pleased with (or He bestowed His Mercy) on so-and-so and his wife (because of their good deed).\" Then Allah revealed: 'But give them preference over themselves even though they were in need of that.' (59.9)","ar":"حَدَّثَنِي يَعْقُوبُ بْنُ إِبْرَاهِيمَ بْنِ كَثِيرٍ، حَدَّثَنَا أَبُو أُسَامَةَ، حَدَّثَنَا فُضَيْلُ بْنُ غَزْوَانَ، حَدَّثَنَا أَبُو حَازِمٍ الأَشْجَعِيُّ، عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ قَالَ أَتَى رَجُلٌ رَسُولَ اللَّهِ صلى الله عليه وسلم فَقَالَ يَا رَسُولَ اللَّهِ أَصَابَنِي الْجَهْدُ فَأَرْسَلَ إِلَى نِسَائِهِ فَلَمْ يَجِدْ عِنْدَهُنَّ شَيْئًا، فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ أَلاَ رَجُلٌ يُضَيِّفُ هَذِهِ اللَّيْلَةَ يَرْحَمُهُ اللَّهُ ‏\"‏‏.‏ فَقَامَ رَجُلٌ مِنَ الأَنْصَارِ فَقَالَ أَنَا يَا رَسُولَ اللَّهِ‏.‏ فَذَهَبَ إِلَى أَهْلِهِ فَقَالَ لاِمْرَأَتِهِ ضَيْفُ رَسُولِ اللَّهِ صلى الله عليه وسلم لاَ تَدَّخِرِيهِ شَيْئًا‏.‏ قَالَتْ وَاللَّهِ مَا عِنْدِي إِلاَّ قُوتُ الصِّبْيَةِ‏.‏ قَالَ فَإِذَا أَرَادَ الصِّبْيَةُ الْعَشَاءَ فَنَوِّمِيهِمْ، وَتَعَالَىْ فَأَطْفِئِي السِّرَاجَ وَنَطْوِي بُطُونَنَا اللَّيْلَةَ‏.‏ فَفَعَلَتْ ثُمَّ غَدَا الرَّجُلُ عَلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَالَ ‏\"‏ لَقَدْ عَجِبَ اللَّهُ عَزَّ وَجَلَّ ـ أَوْ ضَحِكَ ـ مِنْ فُلاَنٍ وَفُلاَنَةَ ‏\"‏‏.‏ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏{‏وَيُؤْثِرُونَ عَلَى أَنْفُسِهِمْ وَلَوْ كَانَ بِهِمْ خَصَاصَةٌ‏}‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 2054b","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-2054b","x":"Abu Huraira reported that a guest spent the night with a person from the Ansar who had nothing with him but food (sufficient) for his own self and his children. He said to his wife:\n\n(Lull) the children to sleep, and put out the lamp, and serve the guest with what you have with you. It was on this occasion that this verse was revealed:\" Those who prefer the needy to their own selves in spite of the fact that they are themselves in pressing need\" (Lix. 9).","ar":"حَدَّثَنَا أَبُو كُرَيْبٍ، مُحَمَّدُ بْنُ الْعَلاَءِ حَدَّثَنَا وَكِيعٌ، عَنْ فُضَيْلِ بْنِ غَزْوَانَ، عَنْ أَبِي، حَازِمٍ عَنْ أَبِي هُرَيْرَةَ، ‏.‏ أَنَّ رَجُلاً، مِنَ الأَنْصَارِ بَاتَ بِهِ ضَيْفٌ فَلَمْ يَكُنْ عِنْدَهُ إِلاَّ قُوتُهُ وَقُوتُ صِبْيَانِهِ فَقَالَ لاِمْرَأَتِهِ نَوِّمِي الصِّبْيَةَ وَأَطْفِئِي السِّرَاجَ وَقَرِّبِي لِلضَّيْفِ مَا عِنْدَكِ - قَالَ - فَنَزَلَتْ هَذِهِ الآيَةُ ‏{‏ وَيُؤْثِرُونَ عَلَى أَنْفُسِهِمْ وَلَوْ كَانَ بِهِمْ خَصَاصَةٌ‏}‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 6, Book 44, Hadith 3304","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-6/Book-44/Hadith-3304","x":"Abu Hurairah narrated:\n\nThat a man from the Ansar had a guest spend the night with him, but he did not have anything to eat but his meal and the meal for his children, so he said to his wife: ‘Put the children to sleep, extinguish the torches, and give me whatever you have with you for the guest.’ So this Ayah was revealed: And they give preference over themselves even though they were in need of that.\"","ar":"حَدَّثَنَا أَبُو كُرَيْبٍ، حَدَّثَنَا وَكِيعٌ، عَنْ فُضَيْلِ بْنِ غَزْوَانَ، عَنْ أَبِي حَازِمٍ، عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَجُلاً، مِنَ الأَنْصَارِ بَاتَ بِهِ ضَيْفٌ فَلَمْ يَكُنْ عِنْدَهُ إِلاَّ قُوتُهُ وَقُوتُ صِبْيَانِهِ فَقَالَ لاِمْرَأَتِهِ نَوِّمِي الصِّبْيَةَ وَأَطْفِئِي السِّرَاجَ وَقَرِّبِي لِلضَّيْفِ مَا عِنْدَكِ فَنَزَلَتْ هَذِهِ الآيَةُُ ‏:‏ ‏(‏ ويؤْثِرُونَ عَلَى أَنْفُسِهِمْ وَلَوْ كَانَ بِهِمْ خَصَاصَةٌ ‏)‏ هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏","v":[]}],"18":[{"c":"Sahih Muslim","r":"Hadith 1017a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-1017a","x":"Mundhir b. Jarir reported on the authority of his father:\n\nWhile we were in the company of the Messenger of Allah (ﷺ) in the early hours of the morning, some people came there (who) were barefooted, naked, wearing striped woollen clothes, or cloaks, with their swords hung (around their necks). Most of them, nay, all of them, belonged to the tribe of Mudar. The colour of the face of the Messenger of Allah (ﷺ) underwent a change when he saw them in poverty. He then entered (his house) and came out and commanded Bilal (to pronounce Adhan). He pronounced Adhan and Iqima, and he (the Holy Prophet) observed prayer (along with his Companion) and then addressed (them reciting verses of the Holy Qur'an): '\" 0 people, fear your Lord, Who created you from a single being\" to the end of the verse,\" Allah is ever a Watcher over you\" (iv. 1). (He then recited) a verse of Sura Hashr:\" Fear Allah. and let every soul consider that which it sends forth for the morrow and fear Allah\" (lix. 18). (Then the audience began to vie with one another in giving charity.) Some donated a dinar, others a dirham, still others clothes, some donated a sa' of wheat, some a sa' of dates; till he (the Holy Prophet) said: (Bring) even if it is half a date. Then a person from among the Ansar came there with a money bag which his hands could scarcely lift; in fact, they could not (lift). Then the people followed continuously, till I saw two heaps of eatables and clothes, and I saw the face of the Messenger (ﷺ) glistening, like gold (on account of joy). The Messenger of Allah (ﷺ) said: He who sets a good precedent in Islam, there is a reward for him for this (act of goodness) and reward of that also who acted according to it subsequently, without any deduction from their rewards; and he who sets in Islam an evil precedent, there is upon him the burden of that, and the burden of him also who acted upon it subsequently, without any deduction from their burden.","ar":"حَدَّثَنِي مُحَمَّدُ بْنُ الْمُثَنَّى الْعَنَزِيُّ، أَخْبَرَنَا مُحَمَّدُ بْنُ جَعْفَرٍ، حَدَّثَنَا شُعْبَةُ، عَنْ عَوْنِ، بْنِ أَبِي جُحَيْفَةَ عَنِ الْمُنْذِرِ بْنِ جَرِيرٍ، عَنْ أَبِيهِ، قَالَ كُنَّا عِنْدَ رَسُولِ اللَّهِ صلى الله عليه وسلم فِي صَدْرِ النَّهَارِ قَالَ فَجَاءَهُ قَوْمٌ حُفَاةٌ عُرَاةٌ مُجْتَابِي النِّمَارِ أَوِ الْعَبَاءِ مُتَقَلِّدِي السُّيُوفِ عَامَّتُهُمْ مِنْ مُضَرَ بَلْ كُلُّهُمْ مِنْ مُضَرَ فَتَمَعَّرَ وَجْهُ رَسُولِ اللَّهِ صلى الله عليه وسلم لِمَا رَأَى بِهِمْ مِنَ الْفَاقَةِ فَدَخَلَ ثُمَّ خَرَجَ فَأَمَرَ بِلاَلاً فَأَذَّنَ وَأَقَامَ فَصَلَّى ثُمَّ خَطَبَ فَقَالَ ‏\"‏ ‏{‏ يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ مِنْ نَفْسٍ وَاحِدَةٍ‏}‏ إِلَى آخِرِ الآيَةِ ‏{‏ إِنَّ اللَّهَ كَانَ عَلَيْكُمْ رَقِيبًا‏}‏ وَالآيَةَ الَّتِي فِي الْحَشْرِ ‏{‏ اتَّقُوا اللَّهَ وَلْتَنْظُرْ نَفْسٌ مَا قَدَّمَتْ لِغَدٍ وَاتَّقُوا اللَّهَ‏}‏ تَصَدَّقَ رَجُلٌ مِنْ دِينَارِهِ مِنْ دِرْهَمِهِ مِنْ ثَوْبِهِ مِنْ صَاعِ بُرِّهِ مِنْ صَاعِ تَمْرِهِ - حَتَّى قَالَ - وَلَوْ بِشِقِّ تَمْرَةٍ ‏\"‏ ‏.‏ قَالَ فَجَاءَ رَجُلٌ مِنَ الأَنْصَارِ بِصُرَّةٍ كَادَتْ كَفُّهُ تَعْجِزُ عَنْهَا بَلْ قَدْ عَجَزَتْ - قَالَ - ثُمَّ تَتَابَعَ النَّاسُ حَتَّى رَأَيْتُ كَوْمَيْنِ مِنْ طَعَامٍ وَثِيَابٍ حَتَّى رَأَيْتُ وَجْهَ رَسُولِ اللَّهِ صلى الله عليه وسلم يَتَهَلَّلُ كَأَنَّهُ مُذْهَبَةٌ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ مَنْ سَنَّ فِي الإِسْلاَمِ سُنَّةً حَسَنَةً فَلَهُ أَجْرُهَا وَأَجْرُ مَنْ عَمِلَ بِهَا بَعْدَهُ مِنْ غَيْرِ أَنْ يَنْقُصَ مِنْ أُجُورِهِمْ شَىْءٌ وَمَنْ سَنَّ فِي الإِسْلاَمِ سُنَّةً سَيِّئَةً كَانَ عَلَيْهِ وِزْرُهَا وَوِزْرُ مَنْ عَمِلَ بِهَا مِنْ بَعْدِهِ مِنْ غَيْرِ أَنْ يَنْقُصَ مِنْ أَوْزَارِهِمْ شَىْءٌ ‏\"‏ ‏.‏","v":[]},{"c":"Riyad as-Salihin","r":"Hadith 171","u":"https://quranx.com/Hadith/Saliheen/Reference/Hadith-171","x":"Jarir bin 'Abdullah (May Allah be pleased with him) reported:\n\nWe were with Messenger of Allah (ﷺ) shortly after dawn when there came to him some people clad in woollen rags, or covered with sleeveless blankets; and with swords hanging down from their necks. Most of them rather, all of them, belonged to the Mudar tribe. The face of the Prophet (ﷺ) changed when he saw them starving. Then he went into his house and came out; then he commanded Bilal (May Allah be pleased with him) to proclaim Adhan (call to prayers). So he proclaimed Adhan and recited Iqamah and the Prophet (ﷺ) led the Salat. Then he delivered a Khutbah saying, \"O mankind! Be dutiful to your Rubb, Who created you from a single person (Adam), and from him (Adam) He created his wife (Eve), and from them both He created many men and women; and fear Allah through Whom you demand your (natural) rights, and do not sever the relations of kinship. Surely, Allah is Ever an All-Watcher over you.\" (4:1) He also recited the Ayah which is in the end of Surat Al-Hashr: \"O you who believe! Fear Allah and keep your duty to Him. And let every one look what he has sent forth for the tomorrow\". (59:18). Thereafter, every man gave in charity Dinar, Dirham, clothes, measure-fulls of wheat and measure-fulls of dates till he said: \"(Give in charity) be it half a date\". Then a man of the Ansar came with a bag which was difficult for him to hold in his hand. Thereafter, the people came successively (with charity) till I saw two heaps of food and clothes. I noticed that the face of Messenger of Allah (ﷺ) was glowing like that of the bright moon or glittering gold. Then he (ﷺ) said, \"Whosoever introduces a good practice in Islam, there is for him its reward and the reward of those who act upon it after him without anything being diminished from their rewards. And whosoever introduces an evil practice in Islam, will shoulder its sin and the sins of all those who will act upon it, without diminishing in any way their burden\"[Muslim].","ar":"عن أبي عمرو، جرير بن عبد الله، رضي الله عنه ، قال‏:‏ كنا في صدر النهار عند رسول الله، صلى الله عليه وسلم، فجاءه قوم عراة مجتابي النمار، أو العباء، متقلدي السيوف، عامتهم من مضر، بل كلهم من مضر؛ فتمعر وجه رسول الله، صلى الله عليه وسلم، لما رأى بهم من الفاقة؛ فدخل ثم خرج، فأمر بلالاً فأذن وأقام، فصلى ثم خطب؛ فقال‏:‏ ‏{‏يا أيها الناس اتقوا ربكم الذي خلقكم من نفس واحدة‏}‏ إلى آخر الآية‏:‏ ‏{‏إن الله كان عليكم رقيبا‏}‏، والآية الأخرى التي في آخر الحشر‏:‏ ‏{‏يا أيها الذين آمنوا اتقوا الله ولتنظر نفس ما قدمت لغد‏}‏ تصدق رجل من ديناره من درهمه من ثوبه من صاع بره من صاع تمره _حتى قال _ ولو بشق تمرة ‏,‏فجاء رجل من الأنصار بصرة كادت كفه تعجز عنها، بل قد عجزت، ثم تتابع الناس حتى رأيت كومين من طعام وثياب، حتى رأيت وجه رسول الله، صلى الله عليه وسلم، يتهلل كأنه مذهبة، فقال رسول الله، صلى الله عليه وسلم، ‏\n\n\"‏ من سن في الإسلام سنة حسنة فله أجرها، وأجر من عمل بها من بعده من غير أن يقنص من أجورهم شيء، ومن سن في الإسلام سنة سيئة كان عليه وزرها ووزر من عمل بها من بعده من غير أن ينقص من أوزارهم شيء‏\"\n\n‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏","v":[]}]};